            {"name": "json_contract", "points": 2, "description": "Returns the requested structured mechanism-diagnosis JSON without reducing the answer to a row-only table or same-scale checklist."},
        ],
    }
    if frame.get("formula_prompt"):
        result["rubric"] = {
            "total_points": 20,
            "criteria": [
                {"name": "mechanism_diagnosis", "points": 3, "description": "Identifies the dominant physical process and gives the correct compact mechanism label or equivalent diagnosis."},
                {"name": "computed_evidence", "points": 4, "description": "Recomputes the package-derived quantitative evidence with correct units, signs, ratios, dates, and rounding."},
                {"name": "formula_derivation", "points": 3, "description": "Shows the requested physical formula, scaling relation, or timing relation and connects it to the computed values."},
                {"name": "evidence_weighting", "points": 3, "description": "Explains which evidence streams are decisive and which are contextual or weaker proxies."},
                {"name": "counterfactual_rejection", "points": 3, "description": "Rejects tempting simplified explanations using computed values rather than assertion."},
                {"name": "bounded_interpretation", "points": 2, "description": "States scale, timing, proxy, or uncertainty limits without adding unsupported losses or impacts."},
                {"name": "json_contract", "points": 2, "description": "Returns the requested structured mechanism-diagnosis JSON without reducing the answer to a row-only table."},
            ],
        }

    return result

def repo_root() -> Path:
    here = Path(__file__).resolve()
    for parent in [here.parent, *here.parents]:
        if (parent / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID).is_dir():
            return parent
    raise FileNotFoundError("Could not locate event data")


def event_root() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


def load_json(rel_path: str) -> Any:
    return json.loads((event_root() / rel_path).read_text(encoding="utf-8-sig"))


def html_text(rel_path: str) -> str:
    parser = TextExtractor()
    parser.feed((event_root() / rel_path).read_text(encoding="utf-8", errors="ignore"))
    return re.sub(r"\s+", " ", " ".join(parser.parts)).strip()


def require(pattern: str, text: str, label: str) -> re.Match[str]:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"Could not extract {label}")
    return match


def parse_impacts(text: str) -> dict[str, int]:
    match = require(
        r"About ([0-9,]+) hectares of eastern England were flooded and ([0-9,]+) people died\. "
        r"A further ([0-9,]+) hectares were flooded in the Netherlands, and ([0-9,]+) people drowned",
        text,
        "impact values",
    )
    england_hectares, england_deaths, netherlands_hectares, netherlands_deaths = [
        int(value.replace(",", "")) for value in match.groups()
    ]
    return {
        "england_flooded_hectares": england_hectares,
        "england_deaths": england_deaths,
        "netherlands_flooded_hectares": netherlands_hectares,
        "netherlands_deaths": netherlands_deaths,
    }


def parse_marine_process(text: str) -> dict[str, Any]:
    thames_match = require(
        r"([0-9,]+) cubic metres of Thames water to flow into the streets",
        text,
        "Thames marine-water volume",
    )
    text_lower = text.lower()
    return {
        "reported_water_surges_and_huge_waves": "water surges and huge waves" in text_lower,
        "reported_coastal_defences_pounded_by_sea": "coastal defences were pounded by the sea" in text_lower,
        "reported_water_overtopped_embankments": "water overtopped embankments" in text_lower,
        "reported_thames_water_inflow_m3": int(thames_match.group(1).replace(",", "")),
        "reported_rainfall_runoff_trigger_in_event_narrative": False,
    }


def parse_report(text: str) -> dict[str, Any]:
    pressure = {
        "south_of_iceland_early_30_jan_mb": int(
            require(
                r"central pressure of ([0-9]+) mb, located a little to the south of Iceland",
                text,
                "996 mb pressure",
            ).group(1)
        ),
        "faeroes_1800_30_jan_mb": int(
            require(r"near the Faeroes, its central pressure ([0-9]+) mb", text, "980 mb pressure").group(1)
        ),
        "north_sea_midday_31_jan_mb": int(
            require(r"over the North Sea .*? central pressure was ([0-9]+) mb", text, "968 mb pressure").group(1)
        ),
        "minimum_before_filling_mb": int(
            require(r"deepened to ([0-9]+) mb before filling", text, "966 mb pressure").group(1)
        ),
    }
    wave_token = require(r"waves more than ([0-9]+|eight) metres high", text, "wave height").group(1).lower()
    return {
        "pressure": pressure,
        "reported_wind_force_text": "Force 10/11",
        "reported_waves_more_than_m": 8 if wave_token == "eight" else int(wave_token),
        "reported_surge_more_in_netherlands_than_norfolk": "even more in the Netherlands" in text,
        "reported_ijmuiden_arrival": "around 4 a.m. on 1 February",
    }


def round3(value: float) -> float:
    return round(value, 3)


def build_output() -> dict[str, Any]:
    event_meta = load_json("metadata/event.json")
    anchor = load_json("data/event_reports/event_reports_003_Locked_event_anchor_1953_North_Sea_storm_surge_flood.json")
    text = html_text("data/event_reports/event_reports_001_Locked_package_evidence_report.html")

    report = parse_report(text)
    impacts = parse_impacts(text)
    marine_process = parse_marine_process(text)
    pressure = report["pressure"]

    pressure_drop_996_to_968 = pressure["south_of_iceland_early_30_jan_mb"] - pressure["north_sea_midday_31_jan_mb"]
    pressure_drop_996_to_966 = pressure["south_of_iceland_early_30_jan_mb"] - pressure["minimum_before_filling_mb"]
    pressure_drop_1013_to_966 = REFERENCE_PRESSURE_MB - pressure["minimum_before_filling_mb"]
    inverse_barometer_rise_m = pressure_drop_1013_to_966 / 100.0
    pressure_metrics = {
        "pressure_drop_996_to_968_mb": pressure_drop_996_to_968,
        "pressure_drop_996_to_966_mb": pressure_drop_996_to_966,
        "pressure_drop_1013_to_966_mb": pressure_drop_1013_to_966,
        "pressure_steps_mb": {
            "996_to_980": pressure["south_of_iceland_early_30_jan_mb"] - pressure["faeroes_1800_30_jan_mb"],
            "980_to_968": pressure["faeroes_1800_30_jan_mb"] - pressure["north_sea_midday_31_jan_mb"],
            "968_to_966": pressure["north_sea_midday_31_jan_mb"] - pressure["minimum_before_filling_mb"],
        },
        "inverse_barometer_rise_m": round(inverse_barometer_rise_m, 2),
        "inverse_barometer_to_three_m_surge_ratio": round3(inverse_barometer_rise_m / SURGE_PROXY_M),
    }

    surge_metrics = {
        "reported_wind_force_text": report["reported_wind_force_text"],
        "reported_surge_proxy_m": SURGE_PROXY_M,
        "reported_waves_more_than_m": report["reported_waves_more_than_m"],
        "wave_to_surge_ratio_lower_bound": round3(report["reported_waves_more_than_m"] / SURGE_PROXY_M),
        "reported_ijmuiden_arrival": report["reported_ijmuiden_arrival"],
        "reported_surge_more_in_netherlands_than_norfolk": report["reported_surge_more_in_netherlands_than_norfolk"],
    }

    marine_process_metrics = {
        **marine_process,
        "reported_surge_proxy_m": SURGE_PROXY_M,
        "reported_waves_more_than_m": report["reported_waves_more_than_m"],
        "wave_to_surge_ratio_lower_bound": round3(report["reported_waves_more_than_m"] / SURGE_PROXY_M),
        "marine_process_evidence_count": sum(
            1
            for key in [
                "reported_water_surges_and_huge_waves",
                "reported_coastal_defences_pounded_by_sea",
                "reported_water_overtopped_embankments",
            ]
            if marine_process[key]
        )
        + int(marine_process["reported_thames_water_inflow_m3"] > 0),
    }

    total_flooded_ha = impacts["england_flooded_hectares"] + impacts["netherlands_flooded_hectares"]
    total_deaths = impacts["england_deaths"] + impacts["netherlands_deaths"]
    impact_metrics = {
        "england_flooded_hectares": impacts["england_flooded_hectares"],
        "netherlands_flooded_hectares": impacts["netherlands_flooded_hectares"],
        "flooded_hectares_total": total_flooded_ha,
        "england_deaths": impacts["england_deaths"],
        "netherlands_deaths": impacts["netherlands_deaths"],
        "deaths_total": total_deaths,
        "england_flooded_share": round3(impacts["england_flooded_hectares"] / total_flooded_ha),
        "netherlands_flooded_share": round3(impacts["netherlands_flooded_hectares"] / total_flooded_ha),
        "england_death_share": round3(impacts["england_deaths"] / total_deaths),
        "netherlands_death_share": round3(impacts["netherlands_deaths"] / total_deaths),
        "death_per_100000_flooded_ha_total": round(total_deaths / total_flooded_ha * 100000, 1),
    }

    row_ids = [
        "pressure_inverse_barometer",
        "surge_wave_tide_amplification",
        "rainfall_runoff_rejection",
        "historical_impact_calibration",
    ]
    rejected_simplifications = ["rainfall_runoff_dominance", "wind_waves_only", "tide_only"]
    storm_surge_ledger = [
        {
            "row_id": "pressure_inverse_barometer",
            "computed_value": pressure_metrics,
            "result": "supports_pressure_forcing_but_rejects_pressure_only",
        },
        {
            "row_id": "surge_wave_tide_amplification",
            "computed_value": surge_metrics,
            "result": "supports_compound_surge_wave_tide_chain",
        },
        {
            "row_id": "rainfall_runoff_rejection",
            "computed_value": marine_process_metrics,
            "result": "rejects_rainfall_runoff_dominance_from_reported_marine_process",
        },
        {
            "row_id": "historical_impact_calibration",
            "computed_value": impact_metrics,
            "result": "calibrates_regional_severity",
        },
    ]

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "target_family": TARGET_FAMILY,
        "primary_gt": {
            "target_family": TARGET_FAMILY,
            "storm_surge_ledger": storm_surge_ledger,
            "rejected_simplifications": rejected_simplifications,
            "final_consistency_label": FINAL_LABEL,
        },
        "key_values": {
            "event_name": event_meta["event_name"],
            "hazard_family": event_meta["hazard_family"],
            "temporal_window": anchor["temporal_window"],
            "pressure_metrics": pressure_metrics,
            "surge_wave_tide_metrics": surge_metrics,
            "marine_process_metrics": marine_process_metrics,
            "impact_metrics": impact_metrics,
            "row_ids": row_ids,
            "numeric_tolerances": {"ratio": 0.01, "depth_m": 0.01, "death_rate": 0.2},
        },
        "rubric": RUBRIC,
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }


def main() -> None:
    output = Path(__file__).resolve().parent / "computed_gt.json"
    result = build_output()
    apply_deepened_task_frame(result)
    output.write_text(json.dumps(result, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
